/* CSS Reset & Base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --accent-pressed: #c73650;
  --border: #0f3460;
  --input-bg: #0f1a2e;
  --shadow: 0 8px 24px rgba(0,0,0,0.4);
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 24px;
  width: 100%;
  max-width: 420px;
}

header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  font-size: 1.75rem;
  letter-spacing: 1px;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
  margin-bottom: 4px;
}

.subtitle {
  font-size: 1rem;
  opacity: 0.8;
}

.calculator {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  border: none;
}

label, legend {
  font-weight: 600;
  font-size: 1rem;
  color: var(--text);
}

input[type="number"] {
  background: var(--input-bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-family: var(--font);
  font-size: 1.125rem;
  padding: 12px 16px;
  width: 100%;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="number"]:focus {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.3);
}

input[type="number"]:hover {
  border-color: var(--accent-hover);
}

.tip-buttons {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

.tip-btn {
  flex: 1;
  min-width: 72px;
  background: var(--input-bg);
  border: 2px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  font-family: var(--font);
  font-size: 1.125rem;
  font-weight: 600;
  padding: 12px 8px;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, transform 0.1s;
}

.tip-btn:hover {
  background: var(--border);
  border-color: var(--accent-hover);
}

.tip-btn:focus-visible {
  outline: none;
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(233, 69, 96, 0.4);
}

.tip-btn[aria-pressed="true"] {
  background: var(--accent);
  border-color: var(--accent);
  color: #fff;
}

.tip-btn[aria-pressed="true"]:hover {
  background: var(--accent-hover);
}

.tip-btn:active {
  transform: scale(0.97);
  background: var(--accent-pressed);
}

.results {
  margin-top: 24px;
  border-top: 2px solid var(--border);
  padding-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-size: 1.125rem;
}

.result-label {
  font-weight: 500;
  opacity: 0.9;
}

.result-value {
  font-weight: 700;
  color: var(--accent);
  font-size: 1.25rem;
}

/* Responsive adjustments */
@media (max-width: 400px) {
  .card {
    padding: 24px 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .tip-buttons {
    gap: 8px;
  }
  .tip-btn {
    padding: 10px 4px;
    font-size: 1rem;
  }
  .result-row {
    font-size: 1rem;
  }
  .result-value {
    font-size: 1.125rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const billInput = document.getElementById('bill');
  const peopleInput = document.getElementById('people');
  const tipButtons = document.querySelectorAll('.tip-btn');
  const tipAmountEl = document.getElementById('tip-amount');
  const totalPerPersonEl = document.getElementById('total-per-person');

  let selectedTip = 0;

  // Initialize tip selection (none pressed by default)
  function setTip(percent) {
    selectedTip = percent;
    tipButtons.forEach(btn => {
      const isActive = Number(btn.dataset.tip) === percent;
      btn.setAttribute('aria-pressed', isActive ? 'true' : 'false');
    });
    calculate();
  }

  // Calculation logic
  function calculate() {
    const bill = parseFloat(billInput.value) || 0;
    const people = parseInt(peopleInput.value, 10) || 1;
    const tipPercent = selectedTip;

    const tip = bill * (tipPercent / 100);
    const totalPerPerson = (bill + tip) / (people > 0 ? people : 1);

    tipAmountEl.textContent = `$${tip.toFixed(2)}`;
    totalPerPersonEl.textContent = `$${totalPerPerson.toFixed(2)}`;
  }

  // Event listeners
  tipButtons.forEach(btn => {
    btn.addEventListener('click', () => {
      setTip(Number(btn.dataset.tip));
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  // Initial calculation
  calculate();
});
